    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 [A01 order dates stored at 23:59:59.999 on June 30: SQL Servers datetime rounds them to July 1, which…', got, ARRAY['SalesPersonID', 'FullName', 'JobTitle', 'SalesTerritory', '2002', '2003', '2004']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'F1  L1', 'Sales Representative', 'Northwest', NULL, '7', '100'),
